(* keep_hierarchy=1 *) module sysface_safe_gate #(parameter integer ID=0,KIND=0)(input A,B,S,output Y);
if(KIND==0) begin:g0 assign Y=A&B; end
else if(KIND==1) begin:g1 assign Y=S?B:A; end
else if(KIND==2) begin:g2 assign Y=~A; end
else if(KIND==3) begin:g3 assign Y=A|B; end
else if(KIND==4) begin:g4 assign Y=A^B; end
else begin:bad initial $error("unsupported gate"); end
endmodule
(* keep_hierarchy=1 *) module sysface_safe_ff #(parameter integer ID=0,KIND=0)(input wire C,D,E,R,output reg Q);
if(KIND==0) begin:g0
always @(posedge C or negedge R) if(!R) Q<=1'b0; else if(!E) Q<=D;
end
else if(KIND==1) begin:g1
always @(posedge C or negedge R) if(!R) Q<=1'b0; else if(E) Q<=D;
end
else if(KIND==2) begin:g2
always @(posedge C) if(E) Q<=D;
end
else if(KIND==3) begin:g3
always @(posedge C or negedge R) if(!R) Q<=1'b0; else Q<=D;
end
else if(KIND==4) begin:g4
always @(posedge C or negedge R) if(!R) Q<=1'b1; else Q<=D;
end
else if(KIND==5) begin:g5
always @(posedge C) Q<=D;
end
else if(KIND==6) begin:g6
always @(posedge C) if(!R) Q<=0; else Q<=D;
end
else if(KIND==7) begin:g7
always @(posedge C) if(R) Q<=0; else Q<=D;
end
else begin:bad initial $error("unsupported FF type"); end
endmodule

